from lib import *
S = SS('w46')
steps = [
    step("RTO 怎么算:往返 100 ms(netlab 每个方向 50 ms)的回环上连续做 15 次“发 100 字节、等回显”,每次发完立刻读 tcp_info(此时重传计时器正在运行)。srtt 一开始就是 100 ms 并保持不变;rttvar(平均偏差)从第 1 次的 37 ms 逐步收敛:28、21、15、12、9、7、5、4、3、3、2、1、1、1 ms;发完立刻读到的 rto 从 500 ms 降到 451、413、385、363、348、338、329、322、317、314、312、310、308、307 ms。对照 srtt + 4 × rttvar:最后一次是 100 + 4 × 1 = 104 ms,而 rto 是 307 ms,相差约 200 ms,正好是 net.inet.tcp.rexmt_slop = 200;第 5 次 148 对 363、第 10 次 112 对 317,差值也是约 200 多一点(rttvar 取整造成的零头)。也就是说本机的 RTO 大致是 srtt + 4 × rttvar + 200 ms 的松弛量。net.inet.tcp.backoff_maximum = 65536(退避封顶,单位 ms)。", t=tl(S(1)), mark=lidx(S(1), '       1            500', '       5            363', '      15            307'), done=lidx(S(1), 'net.inet.tcp.rexmt_slop', 'net.inet.tcp.backoff_maximum', 'RTT 稳定在约 100 ms', '对照公式'), b=bars([['第 1 次 · rto', 500, '500 ms'], ['第 5 次 · rto', 363, '363 ms'], ['第 15 次 · rto', 307, '307 ms'], ['srtt', 100, '100 ms'], ['第 15 次 · srtt + 4×rttvar', 104, '104 ms']], 500, mark=[2], done=[0, 1, 3, 4]), kv=KV([['srtt', '稳定在 100 ms'], ['rttvar', '37 → 1 ms'], ['rto', '500 → 307 ms'], ['rto − (srtt + 4×rttvar)', '≈ 200 ms = rexmt_slop']], ['rto − (srtt + 4×rttvar)'])),
    step("RTO 有下限:不加延迟的回环上(RTT 只有零点几毫秒,srtt 读数 1 ms,rttvar 0 ms),发完立刻读到的 rto 是 230 ms,10 次都一样。也就是说 RTT 再小,RTO 也不会小于 200 多毫秒——否则正常的延迟 ACK 就会引起误重传;下限大致是 rexmt_slop(200 ms)加一点余量。", t=tl(S(2)), mark=lidx(S(2), '不加延迟(lo0 本身)'), done=lidx(S(2), 'RTT 只有零点几毫秒'), b=bars([['lo0 · srtt', 1, '1 ms'], ['lo0 · rto', 230, '230 ms']], 230, mark=[1], done=[0]), kv=KV([['lo0 的 RTT', '约 1 ms'], ['lo0 的 rto', '230 ms'], ['结论', 'RTO 有下限(约 200 ms 以上)']], ['结论'])),
    step("丢包时的重传间隔:netlab 给回环 30% 丢包加单向 50 ms 延迟,做 120 次“发 100 字节、等回显”,用了 55.5 秒;tcp_info 里这条连接发出 188 个包,其中重传 68 个(6800 字节)。抓包按“同一个序号被发送了几次”(相隔 120 ms 以内的按一次算):发送 1 次的 76 个、2 次的 26 个、3 次的 14 个、4 次的 2 个、5 次的 2 个。第 1 次重传距首次发送:44 个样本,最小 301、中位 316、最大 411 ms,与上面测得的 RTO(约 307 ms)吻合;第 2 次重传距第 1 次重传:18 个样本,中位 353(最小 308、最大 704)ms;第 3 次重传距第 2 次:4 个样本,中位 437 ms。间隔确实一次比一次长,但第 2 次 / 第 1 次的中位数之比只有 1.12,并没有看到“每次翻倍”;原因没有深究(样本很少,RTO 会随新的 RTT 样本重新计算,也可能和实现的退避方式有关)。退避的目的是网络拥塞时重传不要加重拥塞,封顶在 backoff_maximum。", t=tl(S(3)), mark=lidx(S(3), '第 1 次重传距首次发送', '第 2 次间隔 / 第 1 次间隔'), done=lidx(S(3), '120 次收发共用', '抓包里 120 个'), b=bars([['第 1 次重传间隔(中位)', 316, '316 ms'], ['第 2 次重传间隔(中位)', 353, '353 ms'], ['第 3 次重传间隔(中位)', 437, '437 ms'], ['若每次翻倍的第 2 次', 632, '632 ms(计算)']], 632, mark=[1, 2], done=[0, 3]), kv=KV([['发送次数', '1 次 76 · 2 次 26 · 3 次 14 · 4 次 2 · 5 次 2'], ['重传间隔(中位)', '316 → 353 → 437 ms'], ['第 2 / 第 1', '1.12:没有看到翻倍'], ['tcp_info', '发出 188 个包,重传 68 个']], ['第 2 / 第 1'])),
]
A = mkartw('w46', 46, '网络协议,TCP,重传,RTO,srtt,rttvar,指数退避,真实验证,动画演示',
    '用 tcp_info 读 srtt / rttvar / rto:RTT 100 ms 时 rto 从 500 ms 收敛到 307 ms ≈ srtt + 4×rttvar + 200 ms 的 rexmt_slop;lo0 上 RTO 下限 230 ms;30% 丢包下首次重传间隔中位 316 ms,之后 353、437 ms,没有看到逐次翻倍。',
    'TCP 靠什么判断一个包丢了?RTO 是怎么算出来的,为什么再快的网络它也有下限?重传间隔是不是真的每次翻倍?这篇用 tcp_info 读内核算出的 srtt / rttvar / rto,再在丢包的回环上抓重传间隔核对。',
    [('307 ms', 'RTT 稳定在 100 ms 之后内核给出的 RTO,约等于 srtt + 4×rttvar + 200 ms(rexmt_slop)'), ('230 ms', 'RTT 只有 1 ms 的回环上 RTO 的下限'), ('316 → 353 → 437 ms', '30% 丢包下首次、第 2 次、第 3 次重传间隔的中位数(没有看到每次翻倍)')],
    [('RTO 的组成', '<p>内核维护平滑 RTT(srtt)和平均偏差(rttvar),RTO ≈ srtt + 4 × rttvar,再加上 rexmt_slop(200 ms)的松弛。RTT 抖动越小 RTO 越小,但有下限。</p>'),
     ('下限', '<p>回环上 RTT 只有 1 ms,RTO 仍是 230 ms,防止延迟 ACK 造成误重传。</p>'),
     ('退避', '<p>丢包时重传间隔逐次变长,封顶在 backoff_maximum(64 秒)。这次实验里 316 → 353 → 437 ms,没有看到严格翻倍,原因没有深究。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上,延迟与丢包由 netlab 注入;srtt / rttvar / rto 来自 TCP_CONNECTION_INFO(单位 ms,取整);第三节的抓包有 dummynet 重复,相隔 120 ms 以内的拷贝按同一次发送处理,重传次数多的样本很少(第 2 / 3 次重传间隔只有 18 个、4 个样本)',
     '没有验证:RTO 达到 backoff_maximum 之后连接被放弃的总时间;en0 真实网络上的重传;Karn 算法(重传段不参与 RTT 采样)的具体表现;尾部丢失探测(TLP)与 RACK 对重传时间的影响;rexmt_slop 能否调整(需要 root)'],
    '超时重传')
